    for i in range(len(nums)):
        current_sum = 0
        for j in range(i, len(nums)):
            current_sum += nums[j]
            if current_sum % 2 != 0:
                total_sum += current_sum
    return total_sum

# Test the function with the provided test case
assert odd_length_sum([1,2,4]) == 14
```

